                { "oid", SC_ASN1_OBJECT, SC_ASN1_TAG_OBJECT, SC_ASN1_ALLOC, NULL, NULL },
                { NULL, 0, 0, 0, NULL, NULL }
        };
        struct sc_asn1_entry asn1_object_id[2];
        int rv;

        sc_copy_asn1_entry(c_asn1_object_id, asn1_object_id);
